});

test('returns different items for different VAT rates', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'PRINT-A4', qty: 100 },
      { sku: 'WORKSHOP-DAY', qty: 1 },
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].vatRate, 9);
  assert.equal(result.value.lines[1].vatRate, 0);
});

test('does not mutate input', () => {
  const lines = [{ sku: 'DES-HOUR', qty: 5 }];
  const originalQty = lines[0].qty;

  createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines,
  });

  assert.equal(lines[0].qty, originalQty);
  assert.equal(lines.length, 1);
});

test('returns a copy, not a reference to input lines', () => {
  const input = [{ sku: 'DES-HOUR', qty: 5 }];
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: input,
  });

  assert.equal(result.ok, true);
  result.value.lines[0].name = 'Modified';
  assert.equal(input[0].name, undefined);
});

test('lineTotal calculates qty times unitPrice', () => {
  assert.equal(lineTotal({ qty: 10, unitPrice: 8500 }), 85000);
  assert.equal(lineTotal({ qty: 1, unitPrice: 1299 }), 1299);
  assert.equal(lineTotal({ qty: 100, unitPrice: 37 }), 3700);
});

test('invoiceTotals sums line totals', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 10, unitPrice: 8500, vatRate: 21 },
      { sku: 'STICKER', name: 'Sticker sheet', qty: 5, unitPrice: 50, vatRate: 21 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 85000 + 250);
  assert.equal(totals.total, 85250);
});

test('invoiceTotals with single line', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 3, unitPrice: 8500, vatRate: 21 }],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 25500);
  assert.equal(totals.total, 25500);
});

test('invoiceTotals with empty lines', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'draft',
    lines: [],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 0);
  assert.equal(totals.total, 0);
});

test('invoiceTotals with various prices', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'draft',
    lines: [
      { sku: 'PRINT-A4', name: 'Printed flyer A4', qty: 50, unitPrice: 37, vatRate: 9 },
      { sku: 'WORKSHOP-DAY', name: 'Brand workshop', qty: 2, unitPrice: 60000, vatRate: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 1850 + 120000);
  assert.equal(totals.total, 121850);
});

test('does not mutate invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 }],
  };

  const originalLines = invoice.lines.length;
  invoiceTotals(invoice);

  assert.equal(invoice.lines.length, originalLines);
  assert.equal(invoice.lines[0].qty, 5);
});

test('addLine adds a new line at the end', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const result = addLine(invoiceResult.value, { sku: 'STICKER', qty: 10 });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 2);
  assert.equal(result.value.lines[1].sku, 'STICKER');
  assert.equal(result.value.lines[1].name, 'Sticker sheet');
  assert.equal(result.value.lines[1].qty, 10);
  assert.equal(result.value.lines[1].unitPrice, 50);
});

test('addLine increases qty if SKU already exists', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const result = addLine(invoiceResult.value, { sku: 'DES-HOUR', qty: 3 });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 1);
  assert.equal(result.value.lines[0].sku, 'DES-HOUR');
  assert.equal(result.value.lines[0].qty, 8);
});

test('addLine reports QTY_INVALID for invalid quantity', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
